struct Queue<T> {
    items: Vec<T>,
}

impl<T> Queue<T> {
    fn new() -> Self {
        Queue { items: vec![] }
    }

    fn push(&mut self, item: T) {
        self.items.push(item);
    }

    fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    fn exchange_first_last(&mut self) {
        if let Some(first) = self.pop() {
            if let Some(last) = self.pop() {
                self.push(first);
                self.push(last);
            } else {
                panic!("Queue has less than two elements");
            }
        } else {
            panic!("Queue is empty");
        }
    }

    fn print_queue(&self) {
        for item in &self.items {
            println!("{}", item);
        }
    }
}

